def normalize_tags(tags):
    if not tags:
        return None

    seen = set()
    result = []
    for tag in tags:
        key = tag.casefold() if isinstance(tag, str) else tag
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return tuple(result)

def most_common_word(words):
    counts = {}
    order = []

    for word in words:
        if word not in counts:
            counts[word] = 0
            order.append(word)
        counts[word] += 1

    if not order:
        return None

    return max(order, key=counts.__getitem__)

def intersection_labels(first, second):
    if not first or not second:
        return None

    second_labels = {label.casefold() for label in second}
    seen = set()
    result = []

    for label in first:
        normalized = label.casefold()
        if normalized in second_labels and normalized not in seen:
            seen.add(normalized)
            result.append(label)

    return tuple(result)

def common_suffix(words):
    words = tuple(words)
    if not words:
        return None

    suffix = words[0]
    for word in words[1:]:
        folded_word = word.casefold()
        while suffix and not folded_word.endswith(suffix.casefold()):
            suffix = suffix[1:]
        if not suffix:
            return ""

    return suffix

def parse_clock(text):
    import re

    match = re.fullmatch(r"(0?[1-9]|1[0-2]):([0-5]\d) ([AaPp][Mm])", text)
    if match is None:
        raise ValueError("invalid clock value")

    hour = int(match.group(1)) % 12
    minute = int(match.group(2))

    if match.group(3).casefold() == "pm":
        hour += 12

    return hour * 60 + minute

def sort_events(events):
    if not events:
        return None
    from datetime import datetime

    def event_time(event):
        value = event["time"]
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        return datetime.fromisoformat(value)

    return tuple(sorted(events, key=event_time))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    left_cols = len(left[0])
    if any(len(row) != left_cols for row in left):
        raise ValueError("left matrix must be rectangular")

    right_cols = len(right[0])
    if any(len(row) != right_cols for row in right):
        raise ValueError("right matrix must be rectangular")

    if left_cols != len(right):
        raise ValueError("left columns must match right rows")

    return [
        [
            sum(left[i][k] * right[k][j] for k in range(left_cols))
            for j in range(right_cols)
        ]
        for i in range(len(left))
    ]

def count_islands(grid):
    if not grid:
        return None

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    islands = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                islands += 1
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    cr, cc = stack.pop()
                    for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                        if (
                            0 <= nr < rows
                            and 0 <= nc < cols
                            and grid[nr][nc] == 1
                            and (nr, nc) not in visited
                        ):
                            visited.add((nr, nc))
                            stack.append((nr, nc))

    return islands
